var ring = root.querySelector('.scl-journey-ring-fg');
var doneEl = root.querySelector('.scl-journey-ring-done');
var steps = Array.prototype.slice.call(root.querySelectorAll('.scl-journey-ring-step'));
if (!view || !steps.length) return;
var LEN = 2 * Math.PI * 18;
ring.style.strokeDasharray = LEN.toFixed(2);
function sync() {
  var n = 0;
  steps.forEach(function (s) { if (s.classList.contains('is-done')) n++; });
  ring.style.strokeDashoffset = (LEN * (1 - n / steps.length)).toFixed(2);
  doneEl.textContent = String(n);
}
steps.forEach(function (s) {
  var btn = s.querySelector('.scl-journey-ring-btn');
  var txt = s.querySelector('.scl-journey-ring-btxt');
  btn.addEventListener('click', function () {
    var on = !s.classList.contains('is-done');
    s.classList.toggle('is-done', on);
    btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    txt.textContent = on ? 'Done' : 'Mark done';
    sync();
  });
});
var queued = false, cur = -1;
function paint() {
  var vr = view.getBoundingClientRect(), line = vr.top + vr.height * 0.45, at = 0;
  for (var i = 0; i < steps.length; i++) { if (steps[i].getBoundingClientRect().top <= line) at = i; }
  if (at === cur) return;
  cur = at;
  steps.forEach(function (s, i) { s.classList.toggle('is-current', i === at); });
}
function tick() {
  if (queued) return;
  queued = true;
  requestAnimationFrame(function () {
    if (!root.isConnected) return;
    queued = false;
    paint();
  });
}
view.addEventListener('scroll', tick, { passive: true });
sync();
paint();
